import{_ as p,r as s,o as l,c as o,e as n,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"{% flash %} - October CMS - 3.x","titleTemplate":false,"description":"Twig 标签","frontmatter":{"subtitle":"Twig 标签"},"headers":[{"level":2,"title":"将闪存消息设置为 Twig 变量","slug":"将闪存消息设置为-twig-变量","link":"#将闪存消息设置为-twig-变量","children":[{"level":4,"title":"参见","slug":"参见","link":"#参见","children":[]}]}],"relativePath":"3.x/zh-cn/markup/tag/flash.md","filePath":"3.x/zh-cn/markup/tag/flash.md"}'),u={name:"3.x/zh-cn/markup/tag/flash.md"};function g(r,a,k,d,m,w){const t=s("pre-heading"),e=s("post-heading");return l(),o("div",null,[n(t),a[0]||(a[0]=c("h1",null,"{% flash %}",-1)),n(e),a[1]||(a[1]=i(`<div class="custom-block aside"><p>查看<a href="./../../cms/features/flash-messages.html">闪存消息文章</a>了解更多关于使用闪存消息的信息。</p></div><p><code>{% flash %}</code> 和 <code>{% endflash %}</code> 标签将渲染存储在用户会话中的任何闪存消息，这些消息由 <code>Flash</code> PHP 类设置。内部的 <code>message</code> 变量将包含闪存消息文本，内部的标记会对多条闪存消息重复显示。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">flash</span> <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> message <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endflash</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>你可以使用 <code>type</code> 变量来表示闪存消息类型 &amp;mdash; <strong>success</strong>、<strong>error</strong>、<strong>info</strong> 或 <strong>warning</strong>。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">flash</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>alert alert-<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> type <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> message <span class="token delimiter punctuation">}}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endflash</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>你也可以指定 <code>type</code> 来过滤给定类型的闪存消息。以下示例将只显示 <strong>success</strong> 消息，如果有 <strong>error</strong> 消息，它不会被显示。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">flash</span> success <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>alert alert-success<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> message <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endflash</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="将闪存消息设置为-twig-变量"><a href="#将闪存消息设置为-twig-变量" class="header-anchor">#</a> 将闪存消息设置为 Twig 变量</h2><p>在任何模板中，你可以使用 <code>flash()</code> 函数将闪存消息设置为变量。这允许你在显示之前操作输出。该函数返回一个数组，每种类型包含一条闪存消息。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> messages <span class="token operator">=</span> flash<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>第一个参数可以指定消息类型，此时返回的消息为字符串。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> successMessage <span class="token operator">=</span> flash<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>success<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>如果第一个参数设置为 <strong>all</strong>，则会返回一个类型数组，每个类型是所有闪存消息的数组。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> allMessages <span class="token operator">=</span> flash<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>all<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h4 id="参见"><a href="#参见" class="header-anchor">#</a> 参见</h4><div class="custom-block also"><ul><li><a href="./../../cms/features/flash-messages.html">闪存消息</a></li></ul></div>`,16))])}const v=p(u,[["render",g]]);export{f as __pageData,v as default};
